from pathlib import Path
import sys,cv2,numpy as np
src=Path(sys.argv[1] if len(sys.argv)>1 else 'source-photo.jpg'); out=Path('assets/source-prepped.png'); img=cv2.imread(str(src)); h,w=img.shape[:2]; crop=img[int(h*.22):int(h*.83),int(w*.28):int(w*.82)]; mask=np.zeros(crop.shape[:2],np.uint8); rect=(int(crop.shape[1]*.1),int(crop.shape[0]*.02),int(crop.shape[1]*.8),int(crop.shape[0]*.96)); bg=np.zeros((1,65),np.float64); fg=np.zeros((1,65),np.float64); cv2.grabCut(crop,mask,rect,bg,fg,7,cv2.GC_INIT_WITH_RECT); mask=np.where((mask==2)|(mask==0),0,255).astype(np.uint8); mask=cv2.GaussianBlur(mask,(0,0),1.2); white=np.full_like(crop,255); a=(mask.astype(np.float32)/255)[...,None]; isolated=(crop*a+white*(1-a)).astype(np.uint8); gray=cv2.cvtColor(isolated,cv2.COLOR_BGR2GRAY); gray=cv2.createCLAHE(clipLimit=2.2,tileGridSize=(8,8)).apply(gray); cv2.imwrite(str(out),gray); print(out)
